	/**
	 * Finds maximal subtrees whose complete model, including scalar conditions and subqueries, uses standard visitor
	 * nodes. Foreign nodes reached through {@code meetOther} remain opaque: neither they nor any containing subtree is
	 * cloned. Their children are still visited to discover independent standard tuple islands. Discovery inspects every
	 * node once and returns roots in stable algebra traversal order without changing any parent links.
	 */
	public static List<TupleExpr> snapshotRoots(TupleExpr root) {
		Objects.requireNonNull(root);
		List<SnapshotNode> nodes = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			private SnapshotNode parent;

			@Override
			protected void meetNode(QueryModelNode node) {
				visit(node, true);
			}

			@Override
			public void meetOther(QueryModelNode node) {
				visit(node, false);
			}

			private void visit(QueryModelNode node, boolean standard) {
				SnapshotNode current = new SnapshotNode(node, parent, standard);
				nodes.add(current);
				parent = current;
				node.visitChildren(this);
				parent = current.parent;
				if (parent != null && !current.standardSubtree) {
					parent.standardSubtree = false;
				}
			}
		});
		List<TupleExpr> roots = new ArrayList<>();
		for (SnapshotNode node : nodes) {
			node.covered = node.parent != null && node.parent.covered;
			if (node.standardSubtree && node.node instanceof TupleExpr tuple) {
				if (!node.covered) {
					roots.add(tuple);
				}
				node.covered = true;
			}
		}
		return List.copyOf(roots);
	}

	private static final class SnapshotNode {
		private final QueryModelNode node;
		private final SnapshotNode parent;
		private boolean standardSubtree;
		private boolean covered;

		private SnapshotNode(QueryModelNode node, SnapshotNode parent, boolean standardSubtree) {
			this.node = node;
			this.parent = parent;
			this.standardSubtree = standardSubtree;
		}
	}

	public Envelope analyze(Filter filter) {
		if (!filterArguments.containsKey(filter)) {
			throw new IllegalArgumentException("The filter does not belong to this algebra generation");
		}
		if (!isCurrent()) {
			throw new IllegalStateException("Filter placements must be rebuilt after an algebra rewrite");
		}
		return new Envelope(filter);
	}

	/** Validates the generation once when preparing all filters of one finalized query. */
	public List<Envelope> analyzeAll() {
		if (!isCurrent()) {
			throw new IllegalStateException("Filter placements must be rebuilt after an algebra rewrite");
		}
		List<Envelope> result = new ArrayList<>(filterArguments.size());
		for (QueryModelNode node : nodes) {
			if (node instanceof Filter filter) {
				result.add(new Envelope(filter));
			}
		}
		return List.copyOf(result);
	}

	public boolean isCurrent() {
		if (substitutedExistsInput != TupleExprs.isPartOfSubQuery(root)
				|| !declaredSubstitutions.equals(TupleExprs.lateralSubstitutedNames(root))) {
			return false;
		}
		for (EnclosingFrame frame : enclosingFrames) {
			if (!frame.isCurrent()) {
				return false;
			}
		}
		List<QueryModelNode> current = collectNodes(root);
		if (current.size() != nodes.size() || !root.equals(snapshot)) {
			return false;
		}
		for (int i = 0; i < nodes.size(); i++) {
			QueryModelNode node = nodes.get(i);
			if (node != current.get(i) || node.getParentNode() != parents.get(node)
					|| node instanceof Filter filter
							&& !filter.getRequiredInputBindingNames().equals(requiredFilterInputs.get(filter))
					|| node instanceof TupleExpr tuple
							&& TupleExprs.isVariableScopeChange(tuple) != scopeFlags.get(tuple)) {
				return false;
			}
		}
		return true;
	}

	/**
	 * Outside producers can model the original frame, but their selected algorithm is outside this proof's lifetime.
	 */
	private record EnclosingFrame(QueryModelNode node, QueryModelNode parent, String algorithm, boolean scopeChange,
			Set<String> requiredInputs) {
		boolean isCurrent() {
			return node.getParentNode() == parent
					&& (!(node instanceof BinaryTupleOperator binary)
							|| Objects.equals(algorithm, binary.getAlgorithmName()))
					&& (!(node instanceof Filter filter)
							|| requiredInputs.equals(filter.getRequiredInputBindingNames()))
					&& (!(node instanceof TupleExpr tuple) || scopeChange == TupleExprs.isVariableScopeChange(tuple));
		}
	}

	private final class Search implements Iterator<Alternative> {
		private final Filter filter;
		private final boolean singletonsOnly;
		private final Predicate<TupleExpr> admissibleSite;
		private final Probe probe;
		private final boolean originProjectionPreserved;
		private final ArrayDeque<Cut> pending = new ArrayDeque<>();
		private final Set<List<Integer>> visited = new HashSet<>();

		private Search(Filter filter, boolean singletonsOnly,
				Predicate<TupleExpr> admissibleSite, Site originalSite, Probe probe) {
			this.filter = filter;
			this.singletonsOnly = singletonsOnly;
			this.admissibleSite = admissibleSite;
			this.probe = probe;
			TupleExpr origin = filterArguments.get(filter);
			Cut originalCut = cut(List.of(origin));
			Site scratchOrigin = probe.site(origin);
			this.originProjectionPreserved = sameConditionProjection(originalSite, scratchOrigin);
			if (originProjectionPreserved) {
				add(originalCut);
			}
		}

		@Override
		public boolean hasNext() {
			return !pending.isEmpty();
		}

		@Override
		public Alternative next() {
			if (!hasNext()) {
				throw new NoSuchElementException();
			}
			Cut current = pending.removeFirst();
			List<Site> sites = new ArrayList<>(current.arguments.size());
			for (TupleExpr argument : current.arguments) {
				sites.add(probe.site(argument));
				List<List<TupleExpr>> children = probe.downward(argument);
				for (List<TupleExpr> replacement : children) {
					if (!singletonsOnly || replacement.size() == 1) {
						add(replace(current, List.of(argument), replacement));
					}
				}
				TupleExpr parent = effectiveParent(argument, filter);
				if (parent == null || parent instanceof QueryRoot || !admissibleSite.test(parent)) {
					continue;
				}
				List<TupleExpr> replaced = List.of(argument);
				if (parent instanceof Union || parent instanceof Intersection) {
					TupleExpr sibling = sibling(parent, argument, filter);
					if (singletonsOnly || !containsIdentity(current.arguments, sibling)) {
						continue;
					}
					replaced = List.of(argument, sibling);
				}
				Cut proposed = replace(current, replaced, List.of(parent));
				if (visited.contains(proposed.ids)) {
					continue;
				}
				if (disjoint(proposed.arguments, filter) && probe.reverseMoveIsLegal(replaced, parent)) {
					add(proposed);
				}
			}
			return new Alternative(sites);
		}

		private void add(Cut candidate) {
			if (candidate.arguments.stream().allMatch(admissibleSite) && disjoint(candidate.arguments, filter)
					&& visited.add(candidate.ids)) {
				pending.addLast(candidate);
			}
		}
	}

	/**
	 * {@link TupleExpr#getBindingNames()} memoized per node. The model recomputes a Join's names from both operands on
	 * every call, so a left-deep chain would cost quadratic time; the operators whose names are exactly the union or
	 * the pass-through of their operands' names are combined from the memoized operands instead. Any other operator,
	 * and any subclass, keeps its own implementation.
	 */
	private Set<String> bindingNamesOf(TupleExpr original) {
		Set<String> names = bindingNames.get(original);
		if (names != null) {
			return names;
		}
		Class<?> type = original.getClass();
		if (type == Join.class || type == LeftJoin.class || type == Union.class) {
			BinaryTupleOperator binary = (BinaryTupleOperator) original;
			Set<String> union = new LinkedHashSet<>(bindingNamesOf(binary.getLeftArg()));
			union.addAll(bindingNamesOf(binary.getRightArg()));
			names = Set.copyOf(union);
		} else if (type == Filter.class && !(((Filter) original).getCondition() instanceof Exists)
				|| type == Distinct.class || type == Reduced.class || type == Slice.class || type == Order.class
				|| type == QueryRoot.class) {
			// A Filter adds its EXISTS sub-query's names; every other listed operator reports its argument's names.
			names = bindingNamesOf(((UnaryTupleOperator) original).getArg());
		} else {
			names = Set.copyOf(original.getBindingNames());
		}
		// Immutable memo values make the Set.copyOf calls downstream free when nothing was removed.
		bindingNames.put(original, names);
		return names;
	}

	/**
	 * A clone of the snapshot with its own binding analysis that is never invalidated. {@code detached} names the one
	 * filter removed from the clone, or {@code null} for the skeleton shared by every filter that can stay in place.
	 */
	private final class Skeleton {
		private final Map<QueryModelNode, QueryModelNode> clones = new IdentityHashMap<>();
		private final Map<QueryModelNode, QueryModelNode> originals = new IdentityHashMap<>();
		private final QueryAlgebraBindingAnalysis bindingAnalysis;
		private final Function<TupleExpr, Set<String>> names = new TupleExprs.DeclaredOutputBindings(clone -> {
			QueryModelNode original = originals.get(clone);
			return original instanceof TupleExpr tuple ? bindingNamesOf(tuple) : clone.getBindingNames();
		});

		private Skeleton(Filter detached) {
			// The shared skeleton never changes structure (gate splices are undone within the call), so the snapshot
			// taken for isCurrent() serves as-is; a detached filter needs a copy of its own.
			TupleExpr copiedRoot = detached == null ? snapshot : snapshot.clone();
			QueryRoot scratch = copiedRoot instanceof QueryRoot queryRoot ? queryRoot : new QueryRoot(copiedRoot);
			List<QueryModelNode> copied = collectNodes(copiedRoot);
			for (int i = 0; i < nodes.size(); i++) {
				clones.put(nodes.get(i), copied.get(i));
				originals.put(copied.get(i), nodes.get(i));
			}
			if (detached != null) {
				Filter clone = (Filter) clones.get(detached);
				clone.replaceWith(clone.getArg());
			}
			this.bindingAnalysis = QueryAlgebraBindingAnalysis.withInputContextAndPossibleInputs(scratch,
					rootInput, Set.of());
		}
	}

	private Skeleton sharedSkeleton;

	private Skeleton sharedSkeleton() {
		if (sharedSkeleton == null) {
			sharedSkeleton = new Skeleton(null);
		}
		return sharedSkeleton;
	}

	/**
	 * Whether evaluating {@code condition} can add binding facts (guaranteed names or value kinds) to the rows that
	 * pass it, as the binding analysis derives them for a Filter: only {@code BOUND} and the {@code isIRI} family do.
	 * Any other filter is fact-transparent: the facts of every other node are the same whether or not it is present.
	 */
	private static boolean narrowsFacts(ValueExpr condition) {
		boolean[] narrows = { false };
		condition.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof Bound || node instanceof IsBNode || node instanceof IsLiteral
						|| node instanceof IsNumeric || node instanceof IsResource || node instanceof IsTriple
						|| node instanceof IsURI) {
					narrows[0] = true;
				} else if (!narrows[0]) {
					super.meetNode(node);
				}
			}
		});
		return narrows[0];
	}

